54	    template <typename T, typename Func>
55	    T WarpOp(T val, Func action)
56	    {
57	        // Shared memory in a warp to guarentee data exchange/modification without data race at warp level.
58	        std::unique_lock<std::mutex> lck(mtx_);
59	        auto currGeneration = syncGeneration;
60	        void* temp = reinterpret_cast<void*>(&data[currGeneration % MEMORY_PIECE]);
61	        T& dataToUpdate = *reinterpret_cast<T*>(temp);
62	        activeThreads--;
63	        if (activeThreads == 0) {
64	            syncGeneration++;
65	            activeThreads = THREAD_PER_WARP;
66	            dataToUpdate = action(val, dataToUpdate);
67	            isReset = false;
68	            cv_.notify_all();
69	        } else {
70	            if (!isReset) {
71	                dataToUpdate = val;
72	                isReset = true;
73	            } else {
74	                dataToUpdate = action(val, dataToUpdate);
75	            }
76	            bool notTimeout = cv_.wait_for(
77	                lck, std::chrono::seconds(5), [this, currGeneration] { return currGeneration != syncGeneration; });
78	            if (!notTimeout) {
79	                KERNEL_LOG(
80	                    KERNEL_ERROR,
81	                    "Warp operation timeout, CPU Debug only supports all 32 threads must be involved in the same "
82	                    "warp operation. If it has already satisfied this condition, maybe deadlock occurred.");
