103	            bool notTimeout = cv_.wait_for(
104	                lck, std::chrono::seconds(5), [this, currGeneration] { return currGeneration != syncGeneration; });
105	            if (!notTimeout) {
106	                KERNEL_LOG(
107	                    KERNEL_ERROR,
108	                    "Shuffle Warp operation timeout, CPU Debug only supports all 32 threads must be involved in the "
