33	const float HALF_SUBNORMAL_THRESHOLD = std::pow(2, -14);
34	} // namespace
35	
36	template <typename T, typename U>
37	constexpr uint32_t GetRoundBitNum()
38	{
39	    if constexpr (std::is_same<T, half>::value && std::is_same<U, float>::value) {
40	        return bfloat16::FP32_MAN_LEN - static_cast<uint32_t>(Fp16BasicParam::K_FP16_MAN_LEN);
41	    } else if constexpr (std::is_same<T, bfloat16_t>::value && std::is_same<U, float>::value) {
42	        return bfloat16::FP32_MAN_LEN - bfloat16::BF16_MAN_LEN;
43	    }
44	    return 0;
45	}
46	
47	template <typename T>
48	constexpr uint32_t GetMantissaLen()
49	{
50	    if constexpr (std::is_same<T, half>::value) {
51	        return static_cast<uint32_t>(Fp16BasicParam::K_FP16_MAN_LEN);
52	    } else if constexpr (std::is_same<T, bfloat16_t>::value) {
53	        return bfloat16::BF16_MAN_LEN;
54	    }
55	    return 0;
56	}
57	
58	template <typename T, typename U, ROUND rnd>
59	void HandleRound(uint32_t sign, int16_t& exp, uint32_t& mantissa, uint32_t round_part)
60	{
61	    constexpr uint32_t round_bit_num = GetRoundBitNum<T, U>();
62	    constexpr uint32_t round_carry = 1U << round_bit_num;
63	    constexpr uint32_t round_bit_map = round_carry - 1;
64	    constexpr uint32_t round_first_bit = 1U << (round_bit_num - 1);
65	    constexpr uint32_t round_left_bit = round_first_bit - 1;
66	
67	    if constexpr (rnd == ROUND::CAST_RINT) {
68	        if ((round_part & round_first_bit) != 0) {
69	            if ((round_part & round_left_bit) != 0) {
70	                mantissa += 1;
71	            } else if ((mantissa & 1) == 1) {
72	                mantissa += 1;
73	            }
74	        }
75	    } else if constexpr (rnd == ROUND::CAST_FLOOR) {
76	        if ((sign == 1) && (round_part != 0)) {
77	            mantissa += 1;
78	        }
79	    } else if constexpr (rnd == ROUND::CAST_CEIL) {
80	        if ((sign == 0) && (round_part != 0)) {
81	            mantissa += 1;
82	        }
83	    } else if constexpr (rnd == ROUND::CAST_ROUND) {
84	        if ((round_part & round_first_bit) != 0) {
85	            mantissa += 1;
86	        }
87	    } else if constexpr (rnd == ROUND::CAST_ODD) {
88	        if ((round_part != 0) && ((mantissa & 1) == 0)) {
89	            mantissa += 1;
90	        }
91	    }
92	
93	    if ((mantissa & (1U << GetMantissaLen<T>())) != 0) {
94	        exp += 1;
95	    }
96	}
97	
98	template <
99	    ROUND rnd = ROUND::CAST_RINT, RoundingSaturation sat = RoundingSaturation::RS_DISABLE_VALUE, typename SRC_TYPE>
100	float CastIntegralToFloat(SRC_TYPE src)
101	{
102	    if constexpr (
103	        rnd == ROUND::CAST_RINT || rnd == ROUND::CAST_FLOOR || rnd == ROUND::CAST_CEIL || rnd == ROUND::CAST_TRUNC) {
104	        fenv_t env;
105	        std::fegetenv(&env);
106	        constexpr int32_t round = [] {
107	            if constexpr (rnd == ROUND::CAST_RINT) {
108	                return FE_TONEAREST;
109	            } else if constexpr (rnd == ROUND::CAST_FLOOR) {
110	                return FE_DOWNWARD;
111	            } else if constexpr (rnd == ROUND::CAST_CEIL) {
112	                return FE_UPWARD;
113	            } else if constexpr (rnd == ROUND::CAST_TRUNC) {
114	                return FE_TOWARDZERO;
115	            }
116	        }();
117	        std::fesetround(round);
118	        float res = static_cast<float>(src);
119	        std::fesetenv(&env);
120	        return res;
121	    }
122	
123	    float f = static_cast<float>(src);
124	    SRC_TYPE tmp = static_cast<SRC_TYPE>(f);
125	    if (src == tmp) {
126	        return f;
127	    }
128	
129	    float f_up = 0;
130	    float f_down = 0;
131	    if (src < tmp) {
132	        f_up = f;
133	        f_down = std::nextafter(f, -INFINITY);
134	    } else {
135	        f_up = std::nextafter(f, INFINITY);
136	        f_down = f;
137	    }
138	
139	    if constexpr (rnd == ROUND::CAST_ROUND) {
140	        SRC_TYPE src_up = static_cast<SRC_TYPE>(f_up);
141	        SRC_TYPE src_down = static_cast<SRC_TYPE>(f_down);
142	        if (src_up - src == src - src_down) {
143	            return src > 0 ? f_up : f_down;
144	        } else if (src_up - src < src - src_down) {
145	            return f_up;
146	        } else {
147	            return f_down;
148	        }
149	    } else if constexpr (rnd == ROUND::CAST_ODD) {
150	        uint32_t f_bits = *reinterpret_cast<uint32_t*>(&f_up);
151	        return (f_bits & 1) == 0 ? f_up : f_down;
152	    }
153	
154	    return static_cast<float>(src);
155	}
156	
157	template <
158	    ROUND rnd = ROUND::CAST_RINT, RoundingSaturation sat = RoundingSaturation::RS_DISABLE_VALUE, typename SRC_TYPE>
159	float __cvt_float(SRC_TYPE src)
160	{
161	    static_assert(
162	        std::is_same_v<SRC_TYPE, int32_t> || std::is_same_v<SRC_TYPE, uint32_t> || std::is_same_v<SRC_TYPE, uint64_t> ||
163	            std::is_same_v<SRC_TYPE, int64_t> || std::is_same_v<SRC_TYPE, half> || std::is_same_v<SRC_TYPE, float> ||
164	            std::is_same_v<SRC_TYPE, bfloat16_t>,
165	        "src type can only be int32_t/uint32_t/int64_t/uint64_t and half/float/bfloat_t");
166	    static_assert(
167	        (rnd == ROUND::CAST_RINT) || (rnd == ROUND::CAST_ROUND) || (rnd == ROUND::CAST_FLOOR) ||
168	            (rnd == ROUND::CAST_CEIL) || (rnd == ROUND::CAST_TRUNC),
169	        "rnd type can only be: ROUND_R, ROUND_A, ROUND_F, ROUND_C,ROUND_Z");
170	
171	    if constexpr (std::is_same_v<SRC_TYPE, half> || std::is_same_v<SRC_TYPE, bfloat16_t>) {
172	        if (__isnan(src)) {
173	            return NAN;
174	        }
175	        if (__isinf(src)) {
176	            return copysignf(INFINITY, src);
177	        }
178	        return src.ToFloat();
179	    } else if constexpr (std::is_same_v<SRC_TYPE, float>) {
180	        if constexpr (rnd == ROUND::CAST_RINT) {
181	            return rintf(src);
182	        } else if constexpr (rnd == ROUND::CAST_ROUND) {
183	            return roundf(src);
184	        } else if constexpr (rnd == ROUND::CAST_FLOOR) {
185	            return floorf(src);
186	        } else if constexpr (rnd == ROUND::CAST_CEIL) {
187	            return ceilf(src);
188	        } else if constexpr (rnd == ROUND::CAST_TRUNC) {
189	            return truncf(src);
190	        } else {
191	            return src;
192	        }
193	    }
194	    if constexpr (std::is_integral<SRC_TYPE>::value) {
195	        return CastIntegralToFloat<rnd, sat>(src);
196	    }
197	    return 0.0f;
198	}
199	
200	template <RoundingSaturation rst, typename T, typename U>
201	bool HandleOverflow(uint16_t sign, int32_t exp, U& res)
202	{
203	    int64_t ctrl48 = AscendC::GetCtrlSpr<48, 48>();
204	    int64_t ctrl60 = AscendC::GetCtrlSpr<60, 60>();
205	    if constexpr (std::is_same_v<T, half>) {
206	        if (exp < 0) { // underflow
207	            res = sign << static_cast<uint16_t>(Fp16BasicParam::K_FP16_SIGN_INDEX);
208	        } else if (exp >= HALF_MAX_EXP) { // overflow
209	            if (ctrl60 == 0) {
210	                if constexpr (rst == RoundingSaturation::RS_DISABLE_VALUE) {
211	                    res = (sign << static_cast<uint16_t>(Fp16BasicParam::K_FP16_SIGN_INDEX)) |
212	                          static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_MASK);
213	                } else {
214	                    res = (sign << static_cast<uint16_t>(Fp16BasicParam::K_FP16_SIGN_INDEX)) |
215	                          static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAX);
216	                }
217	            } else if (ctrl60 == 1) {
218	                if (ctrl48 == 1) {
219	                    res = (sign << static_cast<uint16_t>(Fp16BasicParam::K_FP16_SIGN_INDEX)) |
220	                          static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_MASK);
221	                } else {
222	                    res = (sign << static_cast<uint16_t>(Fp16BasicParam::K_FP16_SIGN_INDEX)) |
223	                          static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAX);
224	                }
225	            }
226	        } else {
227	            return false;
228	        }
229	        return true;
230	    } else if constexpr (std::is_same_v<T, bfloat16_t>) {
231	        if (exp == static_cast<int32_t>(Fp32BasicParam::K_FP32_MAX_EXP)) {
232	            if (ctrl48 == 1) {
233	                res = (sign << bfloat16::BF16_SIGN_INDEX) | bfloat16::BF16_INFINITY;
234	            } else {
235	                res = (sign << bfloat16::BF16_SIGN_INDEX) | bfloat16::BF16_ABS_MAX;
236	            }
237	            return true;
238	        }
239	        return false;
240	    }
241	    return false;
242	}
