244	template <RoundingSaturation rst>
245	bool use_saturation()
246	{
247	    int64_t ctrl60 = AscendC::GetCtrlSpr<60, 60>();
248	    if (ctrl60 == 0)
249	        return (rst == RoundingSaturation::RS_ENABLE_VALUE);
250	    return (AscendC::GetCtrlSpr<48, 48>()) == 0; // 48: ctrl[48]
251	}
