253	template <ROUND rnd, RoundingSaturation rst>
254	half __cvt_half(float x)
255	{
256	    float conform_flag = 0;
257	    if ((x > 0) && x < HALF_SUBNORMAL_THRESHOLD) {
258	        x += HALF_SUBNORMAL_THRESHOLD;
259	        conform_flag = -1;
260	    }
261	    if ((x < 0) && (x > (-1 * HALF_SUBNORMAL_THRESHOLD))) {
262	        x -= HALF_SUBNORMAL_THRESHOLD;
263	        conform_flag = 1;
264	    }
265	
266	    uint32_t f_bits = *reinterpret_cast<uint32_t*>(&x);
267	    uint16_t sign = bfloat16::Fp32ExtracSign(f_bits);
268	    uint32_t exp = bfloat16::Fp32ExtracExp(f_bits);
269	    uint32_t mantissa = f_bits & FP32_MAN_MASK;
270	    uint16_t res = 0;
271	    // handle INF / NaN
272	    if (exp == static_cast<uint32_t>(Fp32BasicParam::K_FP32_MAX_EXP)) {
273	        if (use_saturation<rst>()) {
274	            if (mantissa != 0) {
275	                return half(0);
276	            } else {
277	                // Inf/-Inf
278	                uint16_t half_max = static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAX);
279	                half tmp = *reinterpret_cast<half*>(&half_max);
280	                return (sign == 0) ? tmp : (half)0 - tmp;
281	            }
282	        } else {
283	            res = (sign << static_cast<uint32_t>(Fp16BasicParam::K_FP16_SIGN_INDEX)) |
284	                  (mantissa ? static_cast<uint16_t>(Fp16BasicParam::K_FP16_ABS_MAX) :
285	                              static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_MASK));
286	            return *reinterpret_cast<half*>(&res);
287	        }
288	    }
289	
290	    int16_t half_exp =
291	        static_cast<int16_t>(exp) - (bfloat16::FP32_EXP_BIAS - static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_BIAS));
292	    if (HandleOverflow<rst, half>(sign, half_exp, res)) {
293	        return *reinterpret_cast<half*>(&res);
294	    }
295	
296	    uint32_t round_bit_num = bfloat16::FP32_MAN_LEN - static_cast<uint32_t>(Fp16BasicParam::K_FP16_MAN_LEN);
297	    uint32_t half_mantissa = mantissa >> round_bit_num;
298	    uint32_t round_part = mantissa & ((1 << round_bit_num) - 1);
299	
300	    HandleRound<half, float, rnd>(sign, half_exp, half_mantissa, round_part);
301	    res = (sign << static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_BIAS)) |
302	          (half_exp << static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_LEN)) |
303	          (half_mantissa & static_cast<uint32_t>(Fp16BasicParam::K_FP16_MAN_MASK));
304	    if (HandleOverflow<rst, half>(sign, half_exp, res)) {
305	        return *reinterpret_cast<half*>(&res);
306	    }
307	    half tmp = *reinterpret_cast<half*>(&res);
308	    tmp += half(conform_flag * HALF_SUBNORMAL_THRESHOLD);
309	    return tmp;
310	}
