312	template <ROUND rnd, RoundingSaturation rst>
313	bfloat16_t __cvt_bfloat16_t(float x)
314	{
315	    uint32_t f_bits = *reinterpret_cast<uint32_t*>(&x);
316	    uint16_t sign = bfloat16::Fp32ExtracSign(f_bits);
317	    uint32_t exp = bfloat16::Fp32ExtracExp(f_bits);
318	    uint32_t mantissa = f_bits & FP32_MAN_MASK;
319	    uint16_t res = 0;
320	    // handle INF / NaN
321	    if (exp == static_cast<int32_t>(Fp32BasicParam::K_FP32_MAX_EXP)) {
322	        bool use_saturation = false;
323	        int64_t ctrl60 = AscendC::GetCtrlSpr<60, 60>();
324	        if (ctrl60 == 0) {
325	            use_saturation = (rst == RoundingSaturation::RS_ENABLE_VALUE);
326	        } else {
327	            int64_t ctrl48 = AscendC::GetCtrlSpr<48, 48>();
328	            use_saturation = (ctrl48 == 0);
329	        }
330	        if (use_saturation) { // NaN→0，Inf→max
331	            if (mantissa != 0) {
332	                return bfloat16_t(0);
333	            } else {
334	                // Inf/-Inf
335	                uint16_t bf16_max = static_cast<uint16_t>(0x7F7F);
336	                bfloat16_t tmp = *reinterpret_cast<bfloat16_t*>(&bf16_max);
337	                return (sign == 0) ? tmp : (bfloat16_t)0 - tmp;
338	            }
339	        } else {
340	            res = mantissa == 0 ? ((sign << bfloat16::BF16_SIGN_INDEX) | bfloat16::BF16_EXP_MASK) : bfloat16::BF16_NAN;
341	            return *reinterpret_cast<bfloat16_t*>(&res);
342	        }
343	    }
344	    if (exp == 0 && mantissa == 0) {
345	        res = sign << bfloat16::BF16_SIGN_INDEX;
346	        return *reinterpret_cast<bfloat16_t*>(&res);
347	    }
348	
349	    int16_t bf16_exp = static_cast<int16_t>(exp);
350	    uint32_t round_bit_num = bfloat16::FP32_MAN_LEN - bfloat16::BF16_MAN_LEN;
351	    uint32_t bf16_mantissa = mantissa >> round_bit_num;
352	    uint32_t round_part = mantissa & ((1 << round_bit_num) - 1);
353	
354	    HandleRound<bfloat16_t, float, rnd>(sign, bf16_exp, bf16_mantissa, round_part);
355	    res = (sign << bfloat16::BF16_SIGN_INDEX) | (bf16_exp << bfloat16::BF16_MAN_LEN) |
356	          (bf16_mantissa & bfloat16::BF16_MAN_MASK);
357	    (void)HandleOverflow<rst, bfloat16_t>(sign, bf16_exp, res);
358	
359	    return *reinterpret_cast<bfloat16_t*>(&res);
360	}
