362	template <
363	    ROUND rnd = ROUND::CAST_RINT, RoundingSaturation rst = RoundingSaturation::RS_DISABLE_VALUE, typename SRC_TYPE>
364	half __cvt_half(SRC_TYPE src)
365	{
366	    int64_t ctrl48 = AscendC::GetCtrlSpr<48, 48>();
367	    int64_t ctrl60 = AscendC::GetCtrlSpr<60, 60>();
368	
369	    auto make_half = [](uint16_t bits) { return *reinterpret_cast<half*>(&bits); };
370	
371	    if constexpr (std::is_same_v<SRC_TYPE, half>) {
372	        if (__isnan(src)) {
373	            return ctrl48 == 1 ? make_half(static_cast<uint16_t>(Fp16BasicParam::K_FP16_ABS_MAX)) : half(0);
374	        }
375	        if (__isinf(src)) {
376	            if (ctrl48 == 1) {
377	                return src > (half)0 ? make_half(static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_MASK)) :
378	                                       make_half(0xFC00);
379	            }
380	            half tmp = make_half(static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAX));
381	            return src > (half)0 ? tmp : (half)0 - tmp;
382	        }
383	        float tmp = __cvt_float<rnd, rst>(src);
384	        tmp = __cvt_float<rnd, rst>(tmp);
385	        return __cvt_half<rnd, rst>(tmp);
386	    }
387	
388	    if constexpr (std::is_same_v<SRC_TYPE, bfloat16_t>) {
389	        if (__isnan(src)) {
390	            uint16_t half_nan = static_cast<uint16_t>(Fp16BasicParam::K_FP16_ABS_MAX);
391	            if (ctrl60 == 0) {
392	                return rst == RoundingSaturation::RS_DISABLE_VALUE ? make_half(half_nan) : half(0);
393	            }
394	            return ctrl48 == 1 ? make_half(half_nan) : half(0);
395	        }
396	        float temp = __cvt_float<rnd, rst>(src);
397	        return __cvt_half<rnd, rst>(temp);
398	    }
399	
400	    return half(0);
401	}
