403	template <
404	    ROUND rnd = ROUND::CAST_RINT, RoundingSaturation rst = RoundingSaturation::RS_DISABLE_VALUE, typename SRC_TYPE>
405	bfloat16_t __cvt_bfloat16_t(SRC_TYPE src)
406	{
407	    int64_t ctrl48 = AscendC::GetCtrlSpr<48, 48>();
408	    auto make_bf16 = [](uint16_t bits) { return *reinterpret_cast<bfloat16_t*>(&bits); };
409	
410	    if (__isnan(src)) {
411	        if constexpr (std::is_same_v<SRC_TYPE, bfloat16_t> || std::is_same_v<SRC_TYPE, half>) {
412	            return ctrl48 == 1 ? make_bf16(bfloat16::BF16_NAN) : bfloat16_t(0);
413	        }
414	    }
415	
416	    auto handle_inf = [&](auto zero_val) {
417	        if (ctrl48 == 1) {
418	            return src > zero_val ? make_bf16(static_cast<uint16_t>(bfloat16::BF16_EXP_MASK)) : make_bf16(0xFF80);
419	        }
420	        bfloat16_t tmp = make_bf16(0x7F7F);
421	        return src > zero_val ? tmp : (bfloat16_t)0 - tmp;
422	    };
423	
424	    if constexpr (std::is_same_v<SRC_TYPE, half>) {
425	        if (__isinf(src))
426	            return handle_inf((half)0);
427	        float temp = __cvt_float<rnd, rst>(src);
428	        return __cvt_bfloat16_t<rnd, rst>(temp);
429	    }
430	
431	    if constexpr (std::is_same_v<SRC_TYPE, bfloat16_t>) {
432	        if (__isinf(src))
433	            return handle_inf((bfloat16_t)0);
434	        float temp = __cvt_float<rnd, rst>(src);
435	        temp = __cvt_float<rnd, rst>(temp);
436	        return __cvt_bfloat16_t<rnd, rst>(temp);
437	    }
438	
439	    return bfloat16_t(0);
440	}
