624	        if (ctrl48 == 1) {
625	            auto ConvertHif8ToHalf = [](hifloat8_t hif8) -> half {
626	                uint8_t hif8_bits = *reinterpret_cast<uint8_t*>(&hif8);
627	                // hifloat8 nan: 0x80 -> half nan: 0x7FFF
628	                if (hif8_bits == 0x80) {
629	                    uint16_t half_nan = 0x7FFF;
630	                    return *reinterpret_cast<half*>(&half_nan);
631	                }
632	                // hifloat8 inf: 0x6F -> half inf: 0x7C00
633	                if (hif8_bits == 0x6F) {
634	                    uint16_t half_inf = 0x7C00;
635	                    return *reinterpret_cast<half*>(&half_inf);
636	                }
637	                // hifloat8 -inf: 0xEF -> half -inf: 0xFC00
638	                if (hif8_bits == 0xEF) {
639	                    uint16_t half_neg_inf = 0xFC00;
640	                    return *reinterpret_cast<half*>(&half_neg_inf);
641	                }
642	                return half(hif8.ToFloat());
643	            };
644	            res = {ConvertHif8ToHalf(src.x), ConvertHif8ToHalf(src.y)};
645	        } else {
646	            auto ConvertHif8ToHalfSat = [](hifloat8_t hif8) -> half {
647	                uint8_t hif8_bits = *reinterpret_cast<uint8_t*>(&hif8);
648	                // hifloat8 nan: 0x80 -> half 0
649	                if (hif8_bits == 0x80) {
650	                    return half(0);
651	                }
652	                // hifloat8 inf: 0x6F -> half max: 0x7BFF
653	                if (hif8_bits == 0x6F) {
654	                    uint16_t half_max = 0x7BFF;
655	                    return *reinterpret_cast<half*>(&half_max);
656	                }
657	                // hifloat8 -inf: 0xEF -> half min: 0xFBFF
658	                if (hif8_bits == 0xEF) {
659	                    uint16_t half_min = 0xFBFF;
660	                    return *reinterpret_cast<half*>(&half_min);
661	                }
662	                return half(hif8.ToFloat());
663	            };
664	            res = {ConvertHif8ToHalfSat(src.x), ConvertHif8ToHalfSat(src.y)};
665	        }
666	    } else {
667	        res = {__cvt_half<rnd, rst>(src.x), __cvt_half<rnd, rst>(src.y)};
668	    }
669	    return res;
670	}
