672	template <ROUND rnd, RoundingSaturation rst, typename SRC_TYPE>
673	hifloat8x2_t __cvt_hifloat8x2_t(SRC_TYPE src)
674	{
675	    static_assert(
676	        std::is_same_v<SRC_TYPE, float2> || std::is_same_v<SRC_TYPE, half2>, "src type can only be float2/half2");
677	    static_assert((rnd == ROUND::CAST_ROUND) || (rnd == ROUND::CAST_HYBRID), "rnd type can only be: ROUND_A, ROUND_H");
678	
679	    auto make_hif8 = [](uint8_t bits) { return *reinterpret_cast<hifloat8_t*>(&bits); };
680	
681	    auto ConvertFloatToHiF8 = [&](float f) -> hifloat8_t {
682	        uint32_t f_bits = *reinterpret_cast<uint32_t*>(&f);
683	        uint16_t sign = (f_bits >> 31) & 0x1;
684	        bool is_overflow = (sign == 0 && f_bits >= 0x47200000) || (sign == 1 && f_bits >= 0xC7200000);
685	
686	        if ((f_bits >= 0x47000000) && (f_bits < 0x47200000))
687	            return make_hif8(0x6E);
688	        if ((f_bits >= 0xC7000000) && (f_bits < 0xC7200000))
689	            return make_hif8(0xEE);
690	
691	        if (__isnan(f) || __isinf(f) || is_overflow) {
692	            if (use_saturation<rst>()) {
693	                if (__isnan(f))
694	                    return hifloat8_t(0.0f);
695	                return make_hif8(sign == 1 ? 0xEE : 0x6E);
696	            }
697	            if (__isnan(f))
698	                return make_hif8(0x80);
699	            return make_hif8(sign == 1 ? 0xEF : 0x6F);
700	        }
701	        return hifloat8_t(f);
702	    };
703	
704	    if constexpr (std::is_same_v<SRC_TYPE, float2>) {
705	        return {ConvertFloatToHiF8(src.x), ConvertFloatToHiF8(src.y)};
706	    } else {
707	        float2 tmp{src.x.ToFloat(), src.y.ToFloat()};
708	        return {ConvertFloatToHiF8(tmp.x), ConvertFloatToHiF8(tmp.y)};
709	    }
710	}
711	
712	template <ROUND rnd, RoundingSaturation rst, typename SRC_TYPE>
713	float8_e4m3x2_t __cvt_float8_e4m3x2_t(SRC_TYPE src)
714	{
715	    static_assert(std::is_same_v<SRC_TYPE, float2>, "src type can only be float2");
716	    static_assert(rnd == ROUND::CAST_RINT, "rnd type can only be: ROUND_R");
717	
718	    auto make_fp8 = [](uint8_t bits) { return *reinterpret_cast<fp8_e4m3fn_t*>(&bits); };
719	
720	    auto ConvertFloatToFp8E4M3 = [&](float f) -> fp8_e4m3fn_t {
721	        uint32_t f_bits = *reinterpret_cast<uint32_t*>(&f);
722	        uint16_t exp = (f_bits >> 23) & 0xFF;
723	        uint32_t mantissa = f_bits & 0x7FFFFF;
724	        uint16_t sign = (f_bits >> 31) & 0x1;
725	        bool is_overflow = (exp > 0x87) || ((exp == 0x87) && (mantissa > 0x680000));
726	
727	        if (__isnan(f) || __isinf(f) || is_overflow) {
728	            if (use_saturation<rst>()) {
729	                if (__isnan(f)) {
730	                    int64_t ctrl50 = AscendC::GetCtrlSpr<50, 50>();
731	                    return ctrl50 == 0 ? fp8_e4m3fn_t(0.0f) : make_fp8(0x7F);
732	                }
733	                return make_fp8(sign == 1 ? 0xFE : 0x7E);
734	            }
735	            return make_fp8(0x7F);
736	        }
737	        return fp8_e4m3fn_t(f);
738	    };
739	
740	    return {ConvertFloatToFp8E4M3(src.x), ConvertFloatToFp8E4M3(src.y)};
741	}
742	
743	template <ROUND rnd, RoundingSaturation rst, typename SRC_TYPE>
744	float8_e5m2x2_t __cvt_float8_e5m2x2_t(SRC_TYPE src)
745	{
746	    static_assert(std::is_same_v<SRC_TYPE, float2>, "src type can only be float2");
747	    static_assert(rnd == ROUND::CAST_RINT, "rnd type can only be: ROUND_R");
748	
749	    auto make_fp8 = [](uint8_t bits) { return *reinterpret_cast<fp8_e5m2_t*>(&bits); };
750	
751	    auto ConvertFloatToFp8E5M2 = [&](float f) -> fp8_e5m2_t {
752	        uint32_t f_bits = *reinterpret_cast<uint32_t*>(&f);
753	        uint16_t exp = (f_bits >> 23) & 0xFF;
754	        uint32_t mantissa = f_bits & 0x7FFFFF;
755	        uint16_t sign = (f_bits >> 31) & 0x1;
756	        bool is_overflow = (exp > 0x8E) || ((exp == 0x8E) && (mantissa >= 0x700000));
757	
