763	                }
764	                return make_fp8(sign == 1 ? 0xFB : 0x7B);
765	            }
766	            if (__isnan(f))
767	                return make_fp8(0x7F);
768	            return make_fp8(sign == 1 ? 0xFC : 0x7C);
769	        }
770	        return fp8_e5m2_t(f);
771	    };
772	
773	    return {ConvertFloatToFp8E5M2(src.x), ConvertFloatToFp8E5M2(src.y)};
774	}
