            return src > zero_val ? make_bf16(static_cast<uint16_t>(bfloat16::BF16_EXP_MASK)) : make_bf16(0xFF80);
        }
        bfloat16_t tmp = make_bf16(0x7F7F);
        return src > zero_val ? tmp : (bfloat16_t)0 - tmp;
