    if constexpr (std::is_same_v<SRC_TYPE, bfloat16_t>) {
        if (__isinf(src))
            return handle_inf((bfloat16_t)0);
        float temp = __cvt_float<rnd, rst>(src);
        temp = __cvt_float<rnd, rst>(temp);
        return __cvt_bfloat16_t<rnd, rst>(temp);
