                return make_fp8(sign == 1 ? 0xFE : 0x7E);
            }
            return make_fp8(0x7F);
        }
        return fp8_e4m3fn_t(f);
    };

    return {ConvertFloatToFp8E4M3(src.x), ConvertFloatToFp8E4M3(src.y)};
