template <auto funcPtr, typename... Args>
void async_invoke(const dim3& dim, Args&&... args)
{
    g_threadDimX = dim.x;
    g_threadDimY = dim.y;
    g_threadDimZ = dim.z;

    blockDim.x = g_threadDimX;
    blockDim.y = g_threadDimY;
